import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int n = 0;
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return n;
        }
    }

    static class Element implements Comparable<Element> {
        int height;
        int index;

        Element(int height, int index) {
            this.height = height;
            this.index = index;
        }

        @Override
        public int compareTo(Element o) {
            return Integer.compare(o.height, this.height);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        // Remove consecutive duplicates to simplify
        int[] temp = new int[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || a[i] != a[i - 1]) {
                temp[m++] = a[i];
            }
        }

        Element[] elements = new Element[m];
        for (int i = 0; i < m; i++) {
            elements[i] = new Element(temp[i], i);
        }

        Arrays.sort(elements);

        boolean[] active = new boolean[m];
        int currentComponents = 0;
        int maxComponents = 0;

        int i = 0;
        while (i < m) {
            int j = i;
            while (j < m && elements[j].height == elements[i].height) {
                int idx = elements[j].index;
                active[idx] = true;

                boolean leftActive = (idx > 0 && active[idx - 1]);
                boolean rightActive = (idx < m - 1 && active[idx + 1]);

                if (!leftActive && !rightActive) {
                    currentComponents++;
                } else if (leftActive && rightActive) {
                    currentComponents--;
                }

                j++;
            }

            if (currentComponents > maxComponents) {
                maxComponents = currentComponents;
            }

            i = j;
        }

        System.out.println(maxComponents + 1);
    }
}
